#include <bits/stdc++.h>
using namespace std;

// Пример классической задачи: числа Фибоначчи с мемоизацией
const int MAXN = 100005;
int memo[MAXN];

int fib(int n) {
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];
    // Запоминаем ответ перед возвратом
    return memo[n] = fib(n - 1) + fib(n - 2);
}

int main() {
    int n;
    cin >> n;

    // Top-down (мемоизация)
    memset(memo, -1, sizeof(memo));
    cout << fib(n) << "\n";

    // Bottom-up (табуляция)
    vector<int> dp(n + 1);
    dp[0] = 0;
    if (n > 0) dp[1] = 1;
    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i-1] + dp[i-2];
    }
    cout << dp[n] << "\n";

    return 0;
}
